//! Abdication as a CLAP / VST3 plugin.
//!
//! The sound is the Faust voice in ../dsp, compiled to Rust (`dsp.rs`,
//! generated by tools/gen-rust.sh: don't edit it by hand). This crate adds
//! polyphony (`engine`), host parameters derived from the Faust controls
//! (`params`), the front-panel editor (`editor`), and the nih-plug wrapper
//! below.

use std::sync::Arc;

use nih_plug::prelude::*;

/// The external functions the generated Faust code calls: the wave
/// library, its band-limited basic shapes, and the transient samples.
macro_rules! faust_externs {
    () => {
        #[inline(always)]
        fn wt_sample(index: i32) -> f32 {
            crate::wavelib::sample(index)
        }
        #[inline(always)]
        fn wt_basic(shape: i32, hz: f32, sample_rate: f32, phase: f32) -> f32 {
            crate::wavelib::basic(shape, hz, sample_rate, phase)
        }
        #[inline(always)]
        #[allow(dead_code)]
        fn tr_read(sample: i32, position: f32) -> f32 {
            crate::translib::read(sample, position)
        }
    };
}

/// The voice (dsp/plugin-voice.dsp).
mod dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    faust_externs!();
    include!("dsp.rs");
}

/// A unison copy of the voice's Dual and Wavetable (dsp/plugin-osc.dsp).
mod osc_dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    faust_externs!();
    include!("osc_dsp.rs");
}

/// The voice's events and calls (dsp/plugin-texture.dsp).
mod texture_dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    faust_externs!();
    include!("texture_dsp.rs");
}

/// The calls' echo and reverb (dsp/plugin-callbus.dsp).
mod callbus_dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    faust_externs!();
    include!("callbus_dsp.rs");
}

pub mod wavelib;
pub mod dice;
