use engine::{Engine, Limiter, MAX_BLOCK};
use scope::{LiveScope, ScopePitch};
use params::SynthParams;

pub struct Abdication {
    params: Arc<SynthParams>,
    /// The last note's pitch, which the editor's offline scopes render at.
    scope_pitch: Arc<ScopePitch>,
    /// The newest voice's taps and moving values, for the editor's live screens.
    live_scope: Arc<LiveScope>,
    engine: Engine,
    limiter: Limiter,
    mono: [f32; MAX_BLOCK],
    /// The calls bus, left and right.
    calls: [[f32; MAX_BLOCK]; 2],
}

impl Default for Abdication {
    fn default() -> Self {
        let params = Arc::new(SynthParams::from_faust());
        let mut engine = Engine::new(params.slots());
        let live_scope = Arc::new(LiveScope::default());
        engine.set_live_scope(live_scope.clone());
        Self { params, scope_pitch: Arc::default(), live_scope, engine, limiter: Limiter::new(), mono: [0.0; MAX_BLOCK],
               calls: [[0.0; MAX_BLOCK]; 2] }
    }
}

impl Abdication {
    fn handle(&mut self, event: NoteEvent<()>) {
        match event {
            NoteEvent::NoteOn { channel, note, velocity, .. } => {
                self.scope_pitch.set(engine::note_freq(note));
                self.engine.note_on(channel, note, velocity)
            }
            NoteEvent::NoteOff { channel, note, .. } => self.engine.note_off(channel, note),
            NoteEvent::MidiPitchBend { value, .. } => self.engine.pitch_bend((value - 0.5) * 2.0),
            NoteEvent::MidiCC { cc: 1, value, .. } => {
                self.engine.mod_wheel(value)
            }
            NoteEvent::MidiChannelPressure { pressure, .. } => self.engine.channel_pressure(pressure),
            NoteEvent::PolyPressure { channel, note, pressure, .. } => {
                self.engine.poly_pressure(channel, note, pressure)
            }
            _ => (),
        }
    }
}

impl Plugin for Abdication {
    const NAME: &'static str = "Abdication";
    const VENDOR: &'static str = "Abdicant";
    const URL: &'static str = "";
    const EMAIL: &'static str = "";
    const VERSION: &'static str = env!("CARGO_PKG_VERSION");

    const AUDIO_IO_LAYOUTS: &'static [AudioIOLayout] = &[AudioIOLayout {
        main_input_channels: None,
        main_output_channels: NonZeroU32::new(2),
        ..AudioIOLayout::const_default()
    }];

    const MIDI_INPUT: MidiConfig = MidiConfig::MidiCCs;
    const SAMPLE_ACCURATE_AUTOMATION: bool = true;

    type SysExMessage = ();
    type BackgroundTask = ();

    fn params(&self) -> Arc<dyn Params> {
        self.params.clone()
    }

    fn editor(&mut self, _executor: AsyncExecutor<Self>) -> Option<Box<dyn Editor>> {
        editor::create(self.params.clone(), self.scope_pitch.clone(), self.live_scope.clone())
    }

    fn initialize(
        &mut self,
        _layout: &AudioIOLayout,
        config: &BufferConfig,
        _context: &mut impl InitContext<Self>,
    ) -> bool {
        self.engine.init(config.sample_rate);
        self.limiter.init(config.sample_rate);
        true
    }

    fn reset(&mut self) {
        self.engine.reset();
    }

    fn process(
        &mut self,
        buffer: &mut Buffer,
        _aux: &mut AuxiliaryBuffers,
        context: &mut impl ProcessContext<Self>,
    ) -> ProcessStatus {
        let total = buffer.samples();
        let output = buffer.as_slice();
        let mut next_event = context.next_event();
        let mut start = 0;

        while start < total {
            // Apply every event due by now; end this sub-block at the next one.
            let mut end = (start + MAX_BLOCK).min(total);
            while let Some(event) = next_event {
                let at = event.timing() as usize;
                if at <= start {
                    self.handle(event);
                    next_event = context.next_event();
                } else {
                    end = end.min(at);
                    break;
                }
            }

            self.engine.set_portamento(self.params.glide_seconds());
            // The host's position is for the buffer's start; this sub-block
            // starts `start` samples later.
            let transport = context.transport();
            let tempo = transport.tempo.unwrap_or(120.0);
            let position = transport.playing.then(|| transport.pos_beats()).flatten()
                .map(|beats| beats + start as f64 * tempo / 60.0 / transport.sample_rate as f64);
            self.engine.set_transport(tempo, position, end - start);
            // Plain values per block are enough: Faust smooths its own
            // controls, and draws lines between the modulated ones' values.
            self.engine.load(&self.params);

            let n = end - start;
            self.engine.render(&mut self.mono[..n]);
            let [calls_left, calls_right] = &mut self.calls;
            self.engine.render_calls(&mut calls_left[..n], &mut calls_right[..n]);
            for (i, s) in self.mono[..n].iter().enumerate() {
                let volume = self.params.volume.smoothed.next();
                let (left, right) = self.limiter.process_stereo((s + calls_left[i]) * volume, (s + calls_right[i]) * volume);
                output[0][start + i] = left;
                output[1][start + i] = right;
            }
            start = end;
        }

        ProcessStatus::Normal
    }
}

impl ClapPlugin for Abdication {
    const CLAP_ID: &'static str = "local.abdicant.abdication";
    const CLAP_DESCRIPTION: Option<&'static str> = Some("Personal four-oscillator synthesizer");
    const CLAP_MANUAL_URL: Option<&'static str> = None;
    const CLAP_SUPPORT_URL: Option<&'static str> = None;
    const CLAP_FEATURES: &'static [ClapFeature] =
        &[ClapFeature::Instrument, ClapFeature::Synthesizer, ClapFeature::Stereo];
}

impl Vst3Plugin for Abdication {
    const VST3_CLASS_ID: [u8; 16] = *b"AbdicationAbdcnt";
    const VST3_SUBCATEGORIES: &'static [Vst3SubCategory] =
        &[Vst3SubCategory::Instrument, Vst3SubCategory::Synth, Vst3SubCategory::Stereo];
}

nih_export_clap!(Abdication);
nih_export_vst3!(Abdication);
